#include <vector>

class Solution {
public:
    bool kLengthApart(std::vector<int>& nums, int k) {
        int prev = -1e9;
        for (int i = 0; i < (int)nums.size(); ++i) {
            if (nums[i] == 1) {
                if (i - prev - 1 < k) return false;
                prev = i;
            }
        }
        return true;
    }
};

class Solution {
    public boolean kLengthApart(int[] nums, int k) {
        int prev = -1000000;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] == 1) {
                if (i - prev - 1 < k) return false;
                prev = i;
            }
        }
        return true;
    }
}

